using FluentAssertions;
using NUnit.Framework;
using SWLOR.Game.Server.Feature.ShipComponentDefinition;
using SWLOR.Game.Server.Feature.ShipRewardDefinition;
using SWLOR.Game.Server.Service.SpaceService;

namespace SWLOR.Game.Server.Tests.Service;

/// <summary>
/// Manufacturer components (plan section 14, Appendix D): one per maker, a tier 5 component carrying the maker's trait,
/// from aces and from the salvage of the maker's NPC ships. Generated by tools/SpaceRevampBalance/components.py.
/// </summary>
public class ShipManufacturerTests
{
    [Test]
    public void EveryMaker_HasOneTierFiveComponentCarryingItsOwnTrait()
    {
        var makers = Enum.GetValues<ShipManufacturer>().Where(x => x != ShipManufacturer.Invalid).ToList();
        RevampComponentCatalog.ManufacturerComponents.Select(x => x.Manufacturer).Should().BeEquivalentTo(makers);

        foreach (var component in RevampComponentCatalog.ManufacturerComponents)
        {
            component.Resref.Should().Be(ShipTraitRules.ComponentResref(component.Family, 5),
                "a manufacturer component is its family's tier 5 item, so every tier 5 recipe of the family takes it");
            var trait = ShipTraitRules.Get(component.Trait);
            trait.Name.Should().Be(component.Name);
            trait.Kind.Should().Be(ShipTraitKind.Manufacturer);
            trait.Families.Should().Equal(component.Family);
            trait.Effects.Sum(x => Math.Abs(x.Value)).Should().BeInRange(5, 25, "about a rare trait's budget");
            ShipTraitRules.Pool(component.Family, ShipTraitKind.Rare).Should().NotContain(trait, "salvage never rolls it at random");
            ShipTraitRules.Pool(component.Family, ShipTraitKind.Common).Should().NotContain(trait);
            ShipManufacturerRules.Component(component.Manufacturer).Should().BeSameAs(component);
        }
    }

    [TestCase("t1fighter", ShipManufacturer.Corellian)]
    [TestCase("t3pirgun", ShipManufacturer.Corellian)]
    [TestCase("t5carrier", ShipManufacturer.Corellian)]
    [TestCase("t4gunship", ShipManufacturer.Mandalorian)]
    [TestCase("mandocap2", ShipManufacturer.Mandalorian)]
    [TestCase("t6bomber", ShipManufacturer.Sith)]
    [TestCase("t6pirint", ShipManufacturer.Corellian)]
    [TestCase("sithcap7", ShipManufacturer.Sith)]
    [TestCase("t6sithcusgun", ShipManufacturer.Sith)]
    [TestCase("t1repcusint", ShipManufacturer.Republic)]
    [TestCase("t5repcusgun", ShipManufacturer.Republic)]
    [TestCase("t2czkcusgun", ShipManufacturer.Czerka)]
    [TestCase("ace_hutlar", ShipManufacturer.Chiss)]
    [TestCase("spacemine", ShipManufacturer.Invalid)]
    [TestCase("", ShipManufacturer.Invalid)]
    public void Wrecks_YieldTheMakerTheirShipsResemble(string tag, ShipManufacturer maker)
    {
        ShipManufacturerRules.WreckManufacturer(tag).Should().Be(maker);
    }

    [Test]
    public void EveryNpcShip_HasAMakerItsWreckYields()
    {
        foreach (var ship in RevampNpcShipCatalogTags())
            ShipManufacturerRules.WreckManufacturer(ship).Should().NotBe(ShipManufacturer.Invalid, ship);
    }

    [TestCase(WreckDifficulty.Normal, 1)]
    [TestCase(WreckDifficulty.Elite, 3)]
    [TestCase(WreckDifficulty.Boss, 5)]
    public void SalvageOdds_AreLowOnBasicShipsAndHigherOnElitesAndBosses(WreckDifficulty difficulty, int percent)
    {
        ShipManufacturerRules.SalvagePercent(difficulty).Should().Be(percent);

        ShipManufacturerRules.RollSalvage(ShipManufacturer.Republic, difficulty, _ => percent - 1)
            .Should().Be(("sc_shieldprj_5", ShipComponentTraitType.RepublicShieldMatrix));
        ShipManufacturerRules.RollSalvage(ShipManufacturer.Republic, difficulty, _ => percent).Should().BeNull();
        ShipManufacturerRules.RollSalvage(ShipManufacturer.Invalid, difficulty, _ => 0).Should().BeNull();
    }

    [Test]
    public void ManufacturerTraits_ChangeTheModuleBuiltFromThem()
    {
        var booster = SWLOR.Game.Server.Feature.ShipModuleDefinition.RevampModuleCatalog.Steps.Single(x => x.Tag == "sm_shbst_45");
        var traited = ShipTraitRules.Apply(booster, new[] { ShipComponentTraitType.RepublicShieldMatrix });
        traited.Shield.Should().Be(ShipTraitRules.Scale(booster.Shield, 5));
        ShipTraitRules.DecoratedName("Shield Projector (Tier 5)", new[] { ShipComponentTraitType.RepublicShieldMatrix })
            .Should().Be("Shield Projector (Tier 5) [Republic Shield Matrix]");
    }

    [Test]
    public void SalvageWiring_RollsTheWrecksMakerAndRecordsItOnTheWreck()
    {
        var root = Root();
        File.ReadAllText(Path.Combine(root, "SWLOR.Game.Server", "Feature", "ShipModuleDefinition", "ShipSalvageActions.cs"))
            .Should().Contain("ShipManufacturerRules.RollSalvage(wreck.Manufacturer, wreck.Difficulty, Random.Next)");
        File.ReadAllText(Path.Combine(root, "SWLOR.Game.Server", "Service", "SpaceWrecks.cs"))
            .Should().Contain("ShipManufacturerRules.WreckManufacturer(GetTag(creature))");
    }

    private static IEnumerable<string> RevampNpcShipCatalogTags() =>
        SWLOR.Game.Server.Feature.SpaceObjectDefinition.RevampNpcShipCatalog.Ships.Select(x => x.CreatureTag)
            .Where(x => !RevampAceCatalog.Aces.Any(a => a.Tag == x));

    private static string Root()
    {
        for (var dir = new DirectoryInfo(TestContext.CurrentContext.TestDirectory); dir != null; dir = dir.Parent)
            if (File.Exists(Path.Combine(dir.FullName, "SWLOR.Game.Server.sln"))) return dir.FullName;
        throw new DirectoryNotFoundException("Could not locate the repository.");
    }
}
